    /** The sheet's today on which the person arrived on it by a transfer; null when they did not. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The reason the person is flagged; null when they never were. */
    @Column(name = "flag_reason")
    private String flagReason;

    /** The last day (included) the person's flag is in force; null when they were never flagged. */
    @Column(name = "flag_until")
    private LocalDate flagUntil;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    /** A detached person with the id given and no grade yet, for a revision to fill in (see
     *  {@link PersonRevision#toPerson}). */
    Person(String sheetId, Long id, String name) {
        this.sheetId = sheetId;
        this.id = id;
        this.name = name;
    }

    public Person(String sheetId, String name, String grade, long position) {
        this.sheetId = sheetId;
        this.name = name;
        this.position = position;
        this.grades.add(new GradeFrom(null, grade));
    }

    /** A copy of the person for another sheet (they were transferred there): their name, every
     *  grade they were given (and its from-date), terms, contact, tags and aliases; no holds. They take
     *  the place given in that sheet's list. */
    public Person transferredTo(String toSheetId, long toPosition) {
        return transferredTo(toSheetId, toPosition, null);
    }

    /** As {@link #transferredTo(String, long)}, arriving there on the day given (that sheet's today). */
    public Person transferredTo(String toSheetId, long toPosition, LocalDate arrivedOn) {
        Person copy = new Person(toSheetId, (Long) null, name);
        copy.position = toPosition;
        grades.forEach(g -> copy.grades.add(new GradeFrom(g.getFromDate(), g.getGrade())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new TermsFrom(t.getFromDate(), t.getTerms())));
        copy.contact = contact;
        copy.tags = tags;
        copy.aliases.addAll(aliases);
        copy.origin = sheetId;
        copy.arrivedOn = arrivedOn;
        return copy;
    }

    /** A copy of the person for a clone of their sheet: their name, place in the list, every grade
     *  they were given (and its from-date), terms, contact, aliases, holds, flag, retirement and past
     *  retirements, and the sheet they were transferred from. */
    public Person clonedTo(String toSheetId) {
        Person copy = transferredTo(toSheetId, position);
        copy.origin = origin;
        copy.retiredFrom = retiredFrom;
        retirements.forEach(r -> copy.retirements.add(new Retirement(r.getFromDate(), r.getToDate())));
        holds.forEach(h -> copy.holds.add(new Hold(h.getFromDate(), h.getToDate())));
        copy.flagReason = flagReason;
        copy.flagUntil = flagUntil;
        return copy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
public class PersonController {

    /** What the screen shows of a person; with how many statements were taken of them, and the
     *  last one's due-total (text with two decimals, null when n/a or none) and day (null when none);
     *  whether they are retired, and from which day (null when not); and their past retirements, earliest first; and whether they have any hold, and their holds, earliest first; and their own terms in force on the sheet's today in days (null: none); and their contact (null: none); and their aliases, sorted as names are compared; and whether they clash; and the sheet they were transferred from (null: none); and their tags, sorted, comma and space separated (empty when none); and their snapshots, oldest first, each the day being left and the due-total; and their statements that stand, oldest first by date, each its date and due-total; and their own undated terms (null: none) and their dated terms, earliest first; and the reason of their flag while it is in force on the sheet's today (null: none) (see
     *  {@link PersonService#clashing}).
     *  The grade is the one in force on the sheet's today; grades are all those recorded, each from
     *  its from-date (null: the beginning of time), earliest first. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            List<RetirementView> retirements, boolean held, List<HoldView> holds, Integer terms, String contact, List<String> aliases, boolean clashing, String origin,
            String tags, List<SnapshotView> snapshots, List<StatementLineView> statements, Integer undatedTerms,
            List<TermsView> datedTerms, String flag) {
        public static PersonView of(Person person, StatementSummary statements, LocalDate today,
                boolean clashing) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList(),
                    person.getVersion(), statements.count(),
                    statements.lastDueTotal() == null ? null : statements.lastDueTotal().setScale(2).toPlainString(),
                    statements.lastTakenOn(), person.isRetired(), person.getRetiredFrom(),
                    person.getRetirements().stream().map(r -> new RetirementView(r.getFromDate(), r.getToDate())).toList(),
                    person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    person.termsOn(today), person.getContact(), person.getAliases(), clashing, person.getOrigin(),
                    String.join(", ", Tags.of(person.getTags())),
                    person.getSnapshots().stream().map(s -> new SnapshotView(s.getDay(), s.getDueTotal())).toList(),
                    statements.lines().stream().map(l -> new StatementLineView(l.date(),
                            l.dueTotal() == null ? null : l.dueTotal().setScale(2).toPlainString())).toList(),
                    person.getTerms(),
                    person.getDatedTerms().stream().map(t -> new TermsView(t.getTerms(), t.getFromDate())).toList(),
                    person.flagOn(today));
        }
    }
